export function parseCompleteGameInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCompleteGameInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 12,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      game: getNextAccount(),
      tokenMint: getNextAccount(),
      gameVault: getNextAccount(),
      gameVaultTokenAccount: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      oracle: getNextAccount(),
      oracleOperator: getNextAccount(),
      winner: getNextAccount(),
      creator: getNextAccount(),
      winnerTokenAccount: getNextAccount(),
      oracleOperatorTokenAccount: getNextAccount(),
    },
    data: getCompleteGameInstructionDataDecoder().decode(instruction.data),
  };
}
